  const OpenDialog = () => {
    setOpenDialog(true);
  };

  const OpenSubjectDialog = () => {
    setOpenSubjectDialog(true);
  };

  const toggleOpenDialog = () => setOpenDialog(!openDialog);

  const handleRefresh = () => {
    getClassList();
  };

  const onDeleteRow = useCallback(
    async (classId) => {
      const { data, errors } = await ApiService.deleteClassAsync(classId);
      if (data) {
        setTableData((prev) => prev.filter((row) => row.classId !== classId));
        toast.success('Class deleted successfully.');
        table.onUpdatePageDeleteRow(dataInPage.length);
      } else if (errors) {
        toast.error(errors[0].msg);
      }
      return data;
    },
    [table, dataInPage.length]
  );

  return (
    <DashboardContent>
      <CustomBreadcrumbs
        heading="Manage Class"
        links={[
          { name: 'Dashboard', href: '' },
          { name: 'Class', href: paths.dashboard.class.list },
        ]}
        action={
          <Stack direction="row" spacing={2}>
            <Button
              type="button"
              color="primary"
              variant="outlined"
              aria-haspopup="true"
              sx={{ whiteSpace: 'nowrap' }}
              startIcon={<Iconify icon="mingcute:add-line" />}
              onClick={OpenSubjectDialog}
            >
              Add Subject
            </Button>
            <Button
              variant="contained"
              color="primary"
              startIcon={<Iconify icon="mingcute:add-line" />}
              onClick={OpenDialog}
            >
              New Class
            </Button>
          </Stack>
        }
        sx={{ mb: 2 }}
      />

      <Card>
        <TableToolbar
          filters={filters}
          onFilterChange={handleFilterChange}
          placeholder="Search Class"
        />

        <TableContainer sx={{ height: 'calc(100vh - 40vh)' }}>
          <Box sx={{ position: 'relative' }}>
            <Table stickyHeader size={table.dense ? 'small' : 'medium'}>
              <TableHeadCustom
                order={table.order}
                orderBy={table.orderBy}
                headCells={TABLEHEAD}
                rowCount={dataFiltered.length}
                numSelected={table.selected.length}
                onSort={table.onSort}
              />

              {isLoading ? (
                <TableBody>
                  <TableRow>
                    <TableCell colSpan={TABLEHEAD.length}>
                      <Stack alignItems="center" justifyContent="center" sx={{ py: 5 }}>
                        <LinearProgress
                          sx={{
                            width: '50%',
                            maxWidth: 300,
                          }}
                        />
                      </Stack>
                    </TableCell>
                  </TableRow>
                </TableBody>
              ) : (
                <TableBody>
                  <TableNoData notFound={dataFiltered.length === 0} label="No Class Found." />
                  {dataFiltered.map((row) => (
                    <ClassTableRow
                      key={row.classId}
                      row={row}
                      selected={table.selected.includes(row.classId)}
                      onDeleteRow={() => onDeleteRow(row.classId)}
                      onSuccess={handleRefresh}
                    />
                  ))}

                  <TableEmptyRows
                    height={table.dense ? 56 : 76}
                    emptyRows={emptyRows(table.page, table.rowsPerPage, dataFiltered.length)}
                  />
                </TableBody>
              )}
            </Table>
          </Box>
        </TableContainer>
      </Card>

      <ClassDialog
        open={openDialog}
        onClose={() => setOpenDialog(false)}
        onSuccess={handleRefresh}
      />

      <SubjectDialog
        open={openSubjectDialog}
        onClose={() => setOpenSubjectDialog(false)}
        onSuccess={handleRefresh}
      />
    </DashboardContent>
  );
}

function applyFilter({ inputData, comparator, filters }) {
  const { search } = filters;
  const stabilizedThis = inputData.map((el, index) => [el, index]);

  stabilizedThis.sort((a, b) => {
    const order = comparator(a[0], b[0]);
    return order !== 0 ? order : a[1] - b[1];
  });

  let filteredData = stabilizedThis.map((el) => el[0]);

  if (search) {
    const lower = search.toLowerCase();
    filteredData = filteredData.filter((item) =>
      [item.className].filter(Boolean).some((value) => value.toLowerCase().includes(lower))
    );
  }
  return filteredData;
}

import { useState, useEffect } from 'react';
import { useForm, useFieldArray, Controller } from 'react-hook-form';
import { useNavigate, useLocation } from 'react-router';
import { zodResolver } from '@hookform/resolvers/zod';
import { z as zod } from 'zod';
import {
  Box,
  Card,
  Stack,
  Alert,
  Button,
  Divider,
  TextField,
  Typography,
  Autocomplete,
  CircularProgress,
} from '@mui/material';
import Grid from '@mui/material/Grid2';
import LoadingButton from '@mui/lab/LoadingButton';
import ApiService from 'src/services/ApiService';
import { toast } from 'src/components/snackbar';
import { Iconify } from 'src/components/iconify';
import { LoadingScreen } from 'src/components/loading-screen';
import { Form, Field } from 'src/components/hook-form';
import { useParams } from 'src/routes/hooks';
import { paths } from 'src/routes/paths';

const ExamSchema = zod.object({
  studentClass: zod
    .any()
    .nullable()
    .refine((val) => val !== null, { message: 'Class & Section is required.' }),
  examName: zod.string().trim().min(1, { message: 'Exam name is required.' }),
  maxMarks: zod.coerce.number().positive({ message: 'Max marks must be positive.' }),
  passMarks: zod.coerce.number().nonnegative({ message: 'Pass marks cannot be negative.' }),
  subjects: zod
    .array(
      zod.object({
        subjectId: zod.string(),
        subjectName: zod.string(),
        examDate: zod.string().min(1, { message: 'Date required.' }),
        startTime: zod.string().optional(),
        endTime: zod.string().optional(),
        maxMarks: zod.coerce.number().positive({ message: 'Max marks required.' }),
        passMarks: zod.coerce.number().nonnegative({ message: 'Pass marks ≥ 0.' }),
      })
    )
    .min(1, { message: 'This class has no subjects to schedule.' }),
});

const defaultValues = {
  studentClass: null,
  examName: '',
  maxMarks: '100',
  passMarks: '35',
  subjects: [],
};

export function ExamSaveForm() {
  const navigate = useNavigate();
  const location = useLocation();
  const { id } = useParams();

  const [classMasters, setClassMasters] = useState([]);
  const [fetchingData, setFetchingData] = useState(true);
  const [loadingSubjects, setLoadingSubjects] = useState(false);
  const [saving, setSaving] = useState(false);

  const methods = useForm({
    resolver: zodResolver(ExamSchema),
    defaultValues,
  });

  const {
    reset,
    control,
    handleSubmit,
    formState: { isSubmitting, errors },
  } = methods;

  const { fields } = useFieldArray({ control, name: 'subjects' });

  useEffect(() => {
    const fetchData = async () => {
      setFetchingData(true);

      const classRes = await ApiService.getAllClassMasterSectionsAsync();
      const classList = classRes && classRes.data ? classRes.data : [];
      setClassMasters(classList);

      let initialClass = null;
      let initialExam = null;

      if (id) {
        const examRes = await ApiService.getExamByIdAsync(id);
        initialExam = examRes && examRes.data ? examRes.data : null;
      }

      if (initialExam) {
        initialClass =
          classList.find((c) => c.classId === initialExam.classId) || null;
      } else if (location.state && location.state.classId) {
        initialClass =
          classList.find((c) => c.classId === location.state.classId) || null;
      } else if (classList.length > 0) {
        initialClass = classList[0];
      }

      const baseValues = {
        studentClass: initialClass,
        examName: initialExam && initialExam.examName ? initialExam.examName : '',
        maxMarks: initialExam && initialExam.maxMarks != null ? String(initialExam.maxMarks) : '100',
        passMarks: initialExam && initialExam.passMarks != null ? String(initialExam.passMarks) : '35',
        subjects: [],
      };

      if (initialClass) {
        setLoadingSubjects(true);
        const subRes = await ApiService.getClassSubjectsAsync(initialClass.classId);
        const classSubjects = subRes && subRes.data ? subRes.data : [];

        const existing = {};
        if (initialExam && Array.isArray(initialExam.subjects)) {
          initialExam.subjects.forEach((s) => {
            existing[String(s.subjectId)] = s;
          });
        }

        const rows = classSubjects.map((s) => {
          const prev = existing[String(s.subjectId)];
          return {
            subjectId: String(s.subjectId),
            subjectName: s.subjectName,
            examDate: prev && prev.examDate ? prev.examDate : '',
            startTime: prev && prev.startTime ? String(prev.startTime).slice(0, 5) : '',
            endTime: prev && prev.endTime ? String(prev.endTime).slice(0, 5) : '',
            maxMarks: prev && prev.maxMarks != null ? String(prev.maxMarks) : baseValues.maxMarks,
            passMarks:
              prev && prev.passMarks != null ? String(prev.passMarks) : baseValues.passMarks,
          };
        });

        reset({ ...baseValues, subjects: rows });
        setLoadingSubjects(false);
      } else {
        reset(baseValues);
      }

      setFetchingData(false);
    };

    fetchData();
  }, [id, location.state, reset]);

  const handleClassChange = async (newClass) => {
    methods.setValue('studentClass', newClass, { shouldValidate: true });
    if (!newClass) {
      methods.setValue('subjects', []);
      return;
    }
    setLoadingSubjects(true);
    const subRes = await ApiService.getClassSubjectsAsync(newClass.classId);
    const classSubjects = subRes && subRes.data ? subRes.data : [];
    const currentMaxMarks = methods.getValues('maxMarks') || '100';
    const currentPassMarks = methods.getValues('passMarks') || '35';

    const rows = classSubjects.map((s) => ({
      subjectId: String(s.subjectId),
      subjectName: s.subjectName,
      examDate: '',
      startTime: '',
      endTime: '',
      maxMarks: currentMaxMarks,
      passMarks: currentPassMarks,
    }));
    methods.setValue('subjects', rows, { shouldValidate: true });
    setLoadingSubjects(false);
  };

  const handleSave = handleSubmit(async (values) => {
    setSaving(true);
    try {
      const selectedClass = values.studentClass;
      const firstSubject = values.subjects && values.subjects[0];
      const examMaxMarks = firstSubject ? Number(firstSubject.maxMarks) : (Number(values.maxMarks) || 100);
      const examPassMarks = firstSubject ? Number(firstSubject.passMarks) : (Number(values.passMarks) || 35);

      const payload = {
        examId: id ? Number(id) : null,
        classId: selectedClass ? selectedClass.classId : null,
        examName: values.examName.trim(),
        maxMarks: examMaxMarks,
        passMarks: examPassMarks,
        examDate: null,
        subjects: (values.subjects || []).map((s) => ({
          subjectId: Number(s.subjectId),
          examDate: s.examDate || null,
          startTime: s.startTime || null,
          endTime: s.endTime || null,
          maxMarks: Number(s.maxMarks),
          passMarks: Number(s.passMarks) || 0,
        })),
      };
      const res = await ApiService.saveExamAsync(payload);
      if (res && res.data) {
        toast.success(id ? 'Exam updated successfully.' : 'Exam created successfully.');
        navigate(paths.dashboard.exam.root);
      } else if (res && res.errors && res.errors.length) {
        toast.error(res.errors[0].msg);
      }
    } catch (err) {
      console.error('Failed to save exam:', err);
      toast.error('Failed to save exam.');
    } finally {
      setSaving(false);
    }
  });

  if (fetchingData) {
    return <LoadingScreen />;
  }

  return (
    <Form methods={methods} onSubmit={handleSave}>
      <Grid container spacing={3}>
        <Grid size={12}>
          <Stack spacing={3}>
            <Card sx={{ p: 3 }}>
              <Typography variant="h6" sx={{ mb: 2 }}>
                Exam Information
              </Typography>
              <Stack spacing={2.5}>
                <Controller
                  name="studentClass"
                  control={control}
                  render={({ field }) => (
                    <Autocomplete
                      {...field}
                      fullWidth
                      options={classMasters}
                      value={field.value || null}
                      onChange={(event, newValue) => handleClassChange(newValue)}
                      getOptionLabel={(option) => {
                        if (!option) return '';
                        return option.sectionName
                          ? `${option.className} - ${option.sectionName}`
                          : option.className || '';
                      }}
                      isOptionEqualToValue={(option, value) => {
                        if (!option || !value) return false;
                        return (
                          option.classId === value.classId && option.sectionId === value.sectionId
                        );
                      }}
                      renderInput={(params) => (
                        <TextField
                          {...params}
                          label="Class & Section"
                          placeholder="Select Class & Section"
                          error={Boolean(errors.studentClass)}
                          helperText={
                            errors.studentClass ? errors.studentClass.message : undefined
                          }
                        />
                      )}
                    />
                  )}
                />

                <Field.Text
                  name="examName"
                  label="Exam Name"
                  placeholder="e.g. Mid-Term / Final Exam"
                  fullWidth
                />
              </Stack>
            </Card>

            <Card sx={{ p: 3 }}>
              <Divider sx={{ mb: 2 }}>
                <Typography variant="overline" sx={{ color: 'text.secondary' }}>
                  Datesheet
                </Typography>
              </Divider>

              <Typography variant="caption" sx={{ color: 'text.secondary', display: 'block', mb: 2 }}>
                Set the exam date and schedule for each subject in this class.
              </Typography>

              {loadingSubjects ? (
                <Stack alignItems="center" sx={{ py: 4 }}>
                  <CircularProgress size={30} />
                </Stack>
              ) : fields.length === 0 ? (
                <Alert severity="warning" variant="outlined">
                  This class has no subjects assigned. Add subjects to the class first.
                </Alert>
              ) : (
                <Stack spacing={2}>
                  {fields.map((field, index) => (
                    <Box
                      key={field.id}
                      sx={{
                        p: 2,
                        borderRadius: 1.5,
                        bgcolor: 'background.neutral',
                        border: (theme) => `1px solid ${theme.palette.divider}`,
                      }}
                    >
                      <Stack
                        direction={{ xs: 'column', sm: 'row' }}
                        spacing={2}
                        alignItems={{ sm: 'flex-start' }}
                      >
                        <Stack
                          direction="row"
                          alignItems="center"
                          spacing={1}
                          sx={{ minWidth: 150, pt: { sm: 1 } }}
                        >
                          <Iconify
                            icon="solar:book-2-bold-duotone"
                            sx={{ color: 'primary.main', flexShrink: 0 }}
                          />
                          <Typography variant="subtitle2" noWrap>
                            {field.subjectName}
                          </Typography>
                        </Stack>

                        <Box sx={{ flex: 1, width: 1 }}>
                          <Stack spacing={1.5}>
                            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
                              <Box sx={{ flex: 1.4, minWidth: 0 }}>
                                <Field.DatePicker
                                  name={`subjects.${index}.examDate`}
                                  label="Exam Date"
                                  allowFutureDates
                                  allowPastDates
                                  slotProps={{
                                    textField: {
                                      size: 'small',
                                      fullWidth: true,
                                      sx: { minWidth: 0 },
                                    },
                                  }}
                                />
                              </Box>
                              <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Field.Text
                                  name={`subjects.${index}.startTime`}
                                  label="Start Time"
                                  type="time"
                                  size="small"
                                  fullWidth
                                  slotProps={{ inputLabel: { shrink: true } }}
                                />
                              </Box>
                              <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Field.Text
                                  name={`subjects.${index}.endTime`}
                                  label="End Time"
                                  type="time"
                                  size="small"
                                  fullWidth
                                  slotProps={{ inputLabel: { shrink: true } }}
                                />
                              </Box>
                            </Stack>

                            <Stack direction="row" spacing={1.5}>
                              <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Field.Text
                                  name={`subjects.${index}.maxMarks`}
                                  label="Max Marks"
                                  type="number"
                                  size="small"
                                  fullWidth
                                />
                              </Box>
                              <Box sx={{ flex: 1, minWidth: 0 }}>
                                <Field.Text
                                  name={`subjects.${index}.passMarks`}
                                  label="Pass Marks"
                                  type="number"
                                  size="small"
                                  fullWidth
                                />
                              </Box>
                            </Stack>
                          </Stack>
                        </Box>
                      </Stack>
                    </Box>
                  ))}
                </Stack>
              )}
            </Card>

            <Stack direction="row" spacing={2} justifyContent="flex-start">
              <LoadingButton
                type="submit"
                variant="contained"
                color="primary"
                loading={saving || isSubmitting}
                disabled={loadingSubjects || fields.length === 0}
              >
                {id ? 'Update Exam' : 'Create Exam'}
              </LoadingButton>
              <Button
                variant="outlined"
                color="error"
                onClick={() => navigate(-1)}
                disabled={saving || isSubmitting}
              >
                Cancel
              </Button>
            </Stack>
          </Stack>
        </Grid>
      </Grid>
    </Form>
  );
}

import dayjs from 'dayjs';
import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z as zod } from 'zod';
import {
  Stack,
  Dialog,
  Button,
  MenuItem,
  DialogTitle,
  DialogActions,
  DialogContent,
} from '@mui/material';
import LoadingButton from '@mui/lab/LoadingButton';
import ApiService from 'src/services/ApiService';
import { toast } from 'src/components/snackbar';
import { Form, Field } from 'src/components/hook-form';
import constants from 'src/utils/constants';

// ----------------------------------------------------------------------

const HolidaySchema = zod
  .object({
    holidayName: zod.string().trim().min(1, { message: 'Holiday name is required.' }),
    startDate: zod.string().nullable().refine((val) => !!val, { message: 'Start date is required.' }),
    endDate: zod.string().nullable().optional(),
    holidayType: zod.string().min(1, { message: 'Holiday type is required.' }),
    description: zod.string().optional(),
  })
  .refine(
    (data) => {
      if (data.startDate && data.endDate) {
        return !dayjs(data.endDate).isBefore(dayjs(data.startDate), 'day');
      }
      return true;
    },
    {
      message: 'End date cannot be before start date.',
      path: ['endDate'],
    }
  );

const defaultValues = {
  holidayName: '',
  startDate: dayjs().format('YYYY-MM-DD'),
  endDate: null,
  holidayType: 'NATIONAL',
  description: '',
};

export function HolidayFormDialog({ open, onClose, holiday, onSuccess }) {
  const [saving, setSaving] = useState(false);

  const methods = useForm({
    resolver: zodResolver(HolidaySchema),
    defaultValues,
  });

  const {
    reset,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  useEffect(() => {
    if (!open) return;
    const today = dayjs().format('YYYY-MM-DD');
    reset({
      holidayName: holiday && holiday.holidayName ? holiday.holidayName : '',
      startDate: holiday && holiday.startDate ? holiday.startDate : today,
      endDate: holiday && holiday.endDate ? holiday.endDate : null,
      holidayType: holiday && holiday.holidayType ? holiday.holidayType : 'NATIONAL',
      description: holiday && holiday.description ? holiday.description : '',
    });
  }, [open, holiday, reset]);

  const handleSave = handleSubmit(async (values) => {
    setSaving(true);
    try {
      const startDateFormatted = values.startDate ? dayjs(values.startDate).format('YYYY-MM-DD') : null;
      const endDateFormatted = values.endDate ? dayjs(values.endDate).format('YYYY-MM-DD') : startDateFormatted;

      const payload = {
        holidayId: holiday && holiday.holidayId ? holiday.holidayId : null,
        holidayName: values.holidayName.trim(),
        startDate: startDateFormatted,
        endDate: endDateFormatted,
        holidayType: values.holidayType,
        description: values.description ? values.description.trim() : '',
      };

      const res = await ApiService.saveHolidayAsync(payload);
      if (res && res.data) {
        toast.success(holiday ? 'Holiday updated.' : 'Holiday added.');
        onSuccess();
        onClose();
      } else if (res && res.errors && res.errors.length) {
        toast.error(res.errors[0].msg);
      }
    } catch (err) {
      console.error('Failed to save holiday:', err);
      toast.error('Failed to save holiday.');
    } finally {
      setSaving(false);
    }
  });

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle sx={{ fontWeight: 'bold' }}>
        {holiday ? 'Edit Holiday' : 'New Holiday'}
      </DialogTitle>
      <Form methods={methods} onSubmit={handleSave}>
        <DialogContent>
          <Stack spacing={2.5} sx={{ mt: 0.5 }}>
            <Field.Text name="holidayName" label="Holiday Name" fullWidth />

            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
              <Field.DatePicker name="startDate" label="Start Date" allowFutureDates fullWidth />
              <Field.DatePicker name="endDate" label="End Date (optional)" allowFutureDates fullWidth />
            </Stack>

            <Field.Select name="holidayType" label="Holiday Type" fullWidth>
              {constants.HOLIDAY_TYPE_OPTIONS.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </Field.Select>

            <Field.Text name="description" label="Description / Details (optional)" multiline minRows={2} fullWidth />
          </Stack>
        </DialogContent>
        <DialogActions sx={{ justifyContent: 'flex-start' }}>
          <LoadingButton
            type="submit"
            variant="contained"
            color="primary"
            loading={saving || isSubmitting}
          >
            {holiday ? 'Update' : 'Save'}
          </LoadingButton>
          <Button
            variant="outlined"
            color="error"
            onClick={onClose}
            disabled={saving || isSubmitting}
          >
            Cancel
          </Button>
        </DialogActions>
      </Form>
    </Dialog>
  );
}

import {
  Box,
  Chip,
  TableRow,
  TableCell,
  IconButton,
  Tooltip,
} from '@mui/material';
import { Iconify } from 'src/components/iconify';
import dateHelper from 'src/utils/dateHelper';

// ----------------------------------------------------------------------

const TYPE_COLOR_MAP = {
  NATIONAL: 'error',
  FESTIVAL: 'warning',
  SCHOOL_EVENT: 'info',
  VACATION: 'secondary',
  OTHER: 'default',
};

const TYPE_LABEL_MAP = {
  NATIONAL: 'National Holiday',
  FESTIVAL: 'Festival',
  SCHOOL_EVENT: 'School Event',
  VACATION: 'Vacation / Break',
  OTHER: 'Other',
};

export function HolidayTableRow({ row, selected, onEditRow, onDeleteRow }) {
  const startDateFormatted = row && row.startDate ? dateHelper.formatDate(row.startDate) : '-';
  const endDateFormatted = row && row.endDate ? dateHelper.formatDate(row.endDate) : '-';

  const dateDisplay =
    row && row.startDate && row.endDate && row.startDate !== row.endDate
      ? `${startDateFormatted} - ${endDateFormatted}`
      : startDateFormatted;

  const holidayType = row && row.holidayType ? row.holidayType : 'OTHER';
  const chipColor = TYPE_COLOR_MAP[holidayType] || 'default';
  const chipLabel = TYPE_LABEL_MAP[holidayType] || holidayType.replace('_', ' ');

  return (
    <TableRow hover selected={selected} aria-checked={selected} tabIndex={-1}>
      <TableCell sx={{ fontWeight: 'medium' }}>
        {row && row.holidayName ? row.holidayName : '-'}
      </TableCell>

      <TableCell sx={{ whiteSpace: 'nowrap' }}>
        {dateDisplay}
      </TableCell>

      <TableCell>
        <Chip
          label={chipLabel}
          size="small"
          color={chipColor}
          variant="soft"
        />
      </TableCell>

      <TableCell>
        <Box
          sx={{
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            color: 'text.secondary',
            typography: 'body2',
            maxWidth: 320,
          }}
        >
          {row && row.description ? row.description : '-'}
        </Box>
      </TableCell>

      <TableCell align="center">
        <Box sx={{ display: 'flex', justifyContent: 'center', gap: 1 }}>
          <Tooltip title="Edit" placement="top" arrow>
            <IconButton color="primary" onClick={onEditRow}>
              <Iconify icon="solar:pen-bold" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Delete" placement="top" arrow>
            <IconButton color="error" onClick={onDeleteRow}>
              <Iconify icon="solar:trash-bin-trash-bold" />
            </IconButton>
          </Tooltip>
        </Box>
      </TableCell>
    </TableRow>
  );
}

